// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(depositAmount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();
        uint256 balanceBefore = c.balances(actor);
        vm.assume(balanceBefore == depositAmount);

        vm.prank(actor);
        bool ok;
        try c.CashOut(withdrawAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = c.balances(actor);
        assertTrue(!ok || balanceAfter == balanceBefore - withdrawAmount);
    }
}
